/*
 * The website's lucide icons (lucide-react 1.27.0, ISC licence) as ImageVectors: 24x24, 2px round stroke, no fill.
 * GENERATED by tools/gen-lucide.cjs from the same package the site uses; do not edit by hand, add names to the list instead.
 */
private fun lucide(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f).apply {
        for (d in paths) addPath(
            pathData = addPathNodes(d), fill = null, stroke = SolidColor(Color.Black), strokeLineWidth = 2f,
            strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
        )
    }.build()

